const NL = String.fromCharCode(10);
const now = new Date();
const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
function parseF(f){
  f = String(f||'').trim();
  let m = f.match(/^([0-9]{1,2})[/]([0-9]{1,2})[/]([0-9]{4})$/);
  if(m) return new Date(+m[3], +m[2]-1, +m[1]);
  m = f.match(/^([0-9]{4})-([0-9]{1,2})-([0-9]{1,2})$/);
  if(m) return new Date(+m[1], +m[2]-1, +m[3]);
  const d = new Date(f); return isNaN(d) ? null : new Date(d.getFullYear(), d.getMonth(), d.getDate());
}
const rows = $input.all().map(i => i.json).filter(r => r && r.Nombre);
const fut = rows.filter(r => { const d = parseF(r.Fecha); return d && d >= today; })
                .sort((a,b) => parseF(a.Fecha) - parseF(b.Fecha));
const lista = fut.map(r => '- #' + r.ID + ' | ' + r.Fecha + ' ' + r.Hora + ' - ' + r.Motivo + ' (' + r.Estado + ')').join(NL);
const mensaje = fut.length ? ('Turnos pendientes:' + NL + lista) : 'No tenes turnos pendientes.';
return [{ json: { status: 'success', data: { cantidad: fut.length, turnos: fut, mensaje: mensaje } } }];
